from __future__ import annotations

import ast
import calendar
import csv
import json
import re
from bisect import bisect_right
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET_DIR = Path("/app/dataset")
EMPLOYEES_PATH = DATASET_DIR / "employees.csv"
TASKS_PATH = DATASET_DIR / "tasks.csv"
TIMESHEET_PATH = DATASET_DIR / "timesheet.csv"


def load_employees() -> dict[str, Decimal]:
    with EMPLOYEES_PATH.open(newline="", encoding="utf-8") as file:
        return {
            row["PESEL"]: Decimal(row["hourly_rate"])
            for row in csv.DictReader(file)
        }


def load_task_pays() -> dict[int, Decimal]:
    with TASKS_PATH.open(newline="", encoding="utf-8") as file:
        return {
            int(row["task_id"]): Decimal(row["pay_per_completion"])
            for row in csv.DictReader(file)
        }


def load_timesheet_rows() -> list[dict[str, str]]:
    with TIMESHEET_PATH.open(newline="", encoding="utf-8") as file:
        return list(csv.DictReader(file))


def clamp_date(raw_value: str) -> date:
    year, month, day = map(int, raw_value.split("-"))
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(day, last_day))


def parse_task_ids(raw_value: str) -> list[int]:
    try:
        parsed = ast.literal_eval(raw_value)
        if isinstance(parsed, list):
            return [int(task_id) for task_id in parsed]
    except (SyntaxError, ValueError):
        pass
    return [int(fragment) for fragment in re.findall(r"\d+", raw_value)]


def hamming_distance(left: str, right: str) -> int:
    return sum(left_char != right_char for left_char, right_char in zip(left, right))


def build_employee_id_corrections(
    rows: list[dict[str, str]],
    employee_rates: dict[str, Decimal],
) -> dict[str, str]:
    corrections: dict[str, str] = {}
    valid_ids = list(employee_rates)
    invalid_ids = {
        row["employee_id"] for row in rows if row["employee_id"] not in employee_rates
    }

    for invalid_id in invalid_ids:
        candidates = []
        for valid_id in valid_ids:
            if len(valid_id) != len(invalid_id):
                continue
            candidates.append((hamming_distance(invalid_id, valid_id), valid_id))

        if not candidates:
            continue

        candidates.sort()
        min_distance = candidates[0][0]
        best_ids = [valid_id for distance, valid_id in candidates if distance == min_distance]
        if min_distance <= 3 and len(best_ids) == 1:
            corrections[invalid_id] = best_ids[0]

    return corrections


def first_weekday_in_month(year: int, month: int, weekday: int) -> date:
    first_day = date(year, month, 1)
    delta = (weekday - first_day.weekday()) % 7
    return first_day + timedelta(days=delta)


def build_billing_period_starts(dates: list[date]) -> list[date]:
    if not dates:
        return []

    earliest_date = min(dates)
    latest_date = max(dates)
    anchor_weekday = earliest_date.weekday()

    period_starts: list[date] = []
    year, month = earliest_date.year, earliest_date.month
    while (year, month) <= (latest_date.year, latest_date.month):
        period_starts.append(first_weekday_in_month(year, month, anchor_weekday))
        if month == 12:
            year += 1
            month = 1
        else:
            month += 1

    return period_starts


def round_half_up(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def answer() -> dict[str, list[int]]:
    employee_rates = load_employees()
    task_pays = load_task_pays()
    rows = load_timesheet_rows()

    employee_id_corrections = build_employee_id_corrections(rows, employee_rates)
    corrected_dates = [clamp_date(row["date"]) for row in rows]
    period_starts = build_billing_period_starts(corrected_dates)

    totals: dict[tuple[str, date], Decimal] = defaultdict(lambda: Decimal("0"))

    for row in rows:
        employee_id = row["employee_id"]
        if employee_id not in employee_rates:
            employee_id = employee_id_corrections.get(employee_id, "")
        if employee_id not in employee_rates:
            continue

        work_date = clamp_date(row["date"])
        period_index = bisect_right(period_starts, work_date) - 1
        if period_index < 0:
            continue

        hours_worked = Decimal(row["hours_worked"])
        valid_task_ids = [
            task_id
            for task_id in parse_task_ids(row["performed_tasks"])
            if task_id in task_pays
        ]
        corrected_bonus = sum((task_pays[task_id] for task_id in valid_task_ids), Decimal("0"))
        totals[(employee_id, period_starts[period_index])] += (
            hours_worked * employee_rates[employee_id] + corrected_bonus
        )

    result: dict[str, list[int]] = {}
    for employee_id in sorted(employee_rates):
        monthly_salaries = [
            round_half_up(totals[(employee_id, period_start)])
            for period_start in period_starts
        ]
        result[employee_id] = monthly_salaries

    return result


if __name__ == "__main__":
    with Path("/app/answer.json").open("w", encoding="utf-8") as file:
        json.dump(answer(), file, default=list)
